    "title": "中文：A股市场简报 - 2026-06-02\nEN: A-Share Market Briefing - 2026-06-02",
    "tone": "中文：6月1日市场不是单纯转空，而是指数受科创和光模块拖累、资金转去AI应用与防御资产。今天更适合用稳健底仓加条件单观察回踩，而不是把周一热点当成无条件追涨对象。\nEN: June 1 was not a clean market-wide risk-off day; indices were dragged by STAR and optics while money rotated into AI applications and defensive assets. Today favors steadier base exposure plus conditional pullback watches, not blind continuation chasing of Monday's hot spots.",
