      "中文：先分清楚是内部轮动还是风险偏好继续下滑。6月1日上证指数仅跌0.27%，但科创50跌5.00%、创业板指跌2.15%，说明真正的问题集中在高位科技硬件，而不是所有A股一起转弱。\nEN: First separate internal rotation from a broader drop in risk appetite. On June 1 the SSE Composite slipped only 0.27%, but STAR 50 fell 5.00% and ChiNext 2.15%, showing the real damage was concentrated in crowded tech hardware rather than the whole A-share tape.",
      "中文：成交额回落到2.88万亿元，但市场宽度并不差。媒体统计显示上涨家数仍多于下跌家数，这意味着今天应优先找低位承接与政策执行链，而不是把指数下跌机械解读成全面空头。\nEN: Turnover cooled to RMB 2.88 trillion, but breadth was not poor. Reporting showed advancers still outnumbered decliners, so today's job is to look for lower-risk support and policy-execution chains rather than treating index weakness as automatic full-market bearishness.",
      "中文：流动性短端仍稳。央行6月1日开展1100亿元7天逆回购、操作利率1.40%，10年国债收益率仍在1.7%附近，环境更适合银行、电网、油气这类稳一些的10日波段，而不是追涨停小票。\nEN: Front-end liquidity remains steady. The PBOC conducted RMB 110 billion of 7-day reverse repos at 1.40% on June 1, while the 10-year CGB stayed near 1.7%, an environment that better suits steadier 10-day swings in banks, grid equipment, and energy than chasing limit-up small caps.",
      "中文：地产继续只放在观察和复盘栏里。万科A周一反弹约2.25%，再次提醒此前偏空判断需要承认价格层面的反证，但没有连续两天放量站稳前，不升级为主线多头。\nEN: Property stays in the watch-and-review bucket. Vanke A rebounded about 2.25% on Monday, again forcing acknowledgement that earlier bearish bias met price resistance, but without two sessions of volume-backed follow-through it still does not graduate into a primary long theme.",
